const q = (chapterId: string, number: number, lesson: 1 | 2, prompt: string, texts: readonly [string, string, string, string],
  keys: readonly string[], difficulty: "easy" | "medium" = "medium"): HistoryQuizQuestion => ({
    id: `terpenes-${chapterId}-q${String(number).padStart(2, "0")}`, chapterId, lessonId: "molecules", sectionId: lid(chapterId, lesson),
    prompt, difficulty, options: texts.map((text, index) => ({ id: ["a", "b", "c", "d"][index], text })), sources: refs(...keys),
  });

